import fs from'node:fs';import assert from'node:assert/strict';import crypto from'node:crypto';import{render,sample,overlapCases}from'./clock-v16.mjs';import{render as old}from'../v14/clock-v14.mjs';import{geometry}from'./ring.mjs';
const norm=s=>s.replace(/v6-\d+/g,'ID'),groups=(s,k)=>[...s.matchAll(new RegExp(`<g data-${k}="[^"\\n]+"[\\s\\S]*?<\\/g>`,'g'))].map(m=>norm(m[0]));let cases=0;
for(let end=1;end<=12;end++)for(const o of overlapCases)for(const growth of[0,50,100]){const st={...sample,...o.state,end,firstGrowth:growth,secondGrowth:100-growth},d=render(st),c=old(st,{variant:'C'});for(const k of['hand','growth-number','end-number','growth-ticks'])assert.deepEqual(groups(d,k),groups(c,k));for(const v of['A','B','C'])assert.equal(norm(render(st,{variant:v})),norm(old(st,{variant:v})));assert.equal((d.match(/data-main-number=/g)||[]).length,12);for(const g of groups(d,'main-number'))assert.ok(g.includes('font-size="52"')&&g.includes("Georgia,serif"));assert.ok(d.includes('data-ring-centerline="true" cx="512" cy="500" r="347"'));cases++;}
assert.equal(geometry.cx,512);assert.equal(geometry.cy,500);assert.equal(geometry.r,347);
const s=fs.readFileSync(new URL('stand-A.svg',import.meta.url),'utf8'),b=Buffer.from(s.match(/data:image\/jpeg;base64,([^"]+)/)[1],'base64'),d=fs.readFileSync(new URL('evidence/D-full.jpg',import.meta.url));assert.deepEqual(b,d);assert.notDeepEqual(d,fs.readFileSync(new URL('../v15/evidence/D-full.jpg',import.meta.url)));const rows=JSON.parse(fs.readFileSync(new URL('evidence/clearance.json',import.meta.url))).rows;assert.ok(rows.every(r=>Math.min(r.silver,r.ticks,r.bezel)>0));assert.ok(rows[9].silver>=8&&rows[9].ticks>=8);console.log({cases,referenceABC:true,handsSubdialsPreserved:true,ring:geometry,ten:rows[9],standSha256:crypto.createHash('sha256').update(d).digest('hex'),differentFromV15:true});
